profile:
{
  "version": 1,
  "services": [
    "gate",
    "api",
    "godot-api",
    "postgres",
    "redis",
    "migrate"
  ],
  "image_prefixes": [
    "ghcr.io/aviorstudio/fieldsofrevik-preview-gate:",
    "ghcr.io/aviorstudio/fieldsofrevik-preview-api:",
    "ghcr.io/aviorstudio/fieldsofrevik-preview-godot-api:",
    "ghcr.io/aviorstudio/fieldsofrevik-preview-postgres:"
  ],
  "credential_namespace": "komizo-revik-preview:",
  "credentials": [
    "admin",
    "migrator",
    "runtime",
    "backup",
    "bridge"
  ],
  "environment_rules": [
    {
      "name": "CLERK_SECRET_KEY",
      "pattern": "^sk_test_[A-Za-z0-9_-]{8,193}$"
    },
    {
      "name": "CLERK_ISSUER",
      "pattern": "^https://[a-z0-9-]+\.clerk\.accounts\.dev$"
    },
    {
      "name": "CLERK_JWKS_URL",
      "equals_field": "CLERK_ISSUER",
      "suffix": "/.well-known/jwks.json"
    }
  ],
  "compose_template": "
# Written by komizo preview. Every volume and private network belongs to this PR.
x-runtime: &runtime
{{if .CgroupParent}}  cgroup_parent: {{.CgroupParent}}
{{end}}  restart: unless-stopped
  read_only: true
  cap_drop: [ALL]
  security_opt: [no-new-privileges:true]
  pids_limit: 128
  cpu_shares: 128
  cpus: {{.CPULimit}}
  tmpfs: ["/tmp:rw,noexec,nosuid,size=64m,mode=1777"]
services:
  postgres:
    <<: *runtime
    mem_limit: {{index .Limits "postgres"}}
    memswap_limit: {{index .Limits "postgres"}}
    image: {{index .Images 3}}
    cap_add: [CHOWN, DAC_OVERRIDE, FOWNER, SETGID, SETUID]
    tmpfs: ["/tmp:rw,nosuid,size=32m,mode=1777", "/var/run/postgresql:rw,nosuid,size=16m,mode=1777"]
    environment:
      POSTGRES_USER: postgres
      POSTGRES_DB: postgres
      PGDATA: /var/lib/postgresql/data
      POSTGRES_PASSWORD: {{index .Credentials "admin"}}
      REVIK_MIGRATOR_PASSWORD: {{index .Credentials "migrator"}}
      REVIK_APP_PASSWORD: {{index .Credentials "runtime"}}
      REVIK_BACKUP_PASSWORD: {{index .Credentials "backup"}}
    volumes: [pg_data:/var/lib/postgresql/data]
    networks: [db]
    healthcheck:
      test: [CMD-SHELL, 'test "$$(cat /proc/1/comm)" = postgres && pg_isready -d revik -U postgres']
      interval: 5s
      timeout: 3s
      retries: 24
      start_period: 20s
  migrate:
    <<: *runtime
    mem_limit: {{index .Limits "migrate"}}
    memswap_limit: {{index .Limits "migrate"}}
    image: {{index .Images 1}}
    restart: "no"
    entrypoint: [/app/server, migrate]
    environment:
      DATABASE_MIGRATION_URL: postgres://revik_migrator:{{index .Credentials "migrator"}}@postgres:5432/revik?sslmode=disable
    networks: [db]
    depends_on:
      postgres: {condition: service_healthy}
  api:
    <<: *runtime
    mem_limit: {{index .Limits "api"}}
    memswap_limit: {{index .Limits "api"}}
    image: {{index .Images 1}}
    env_file: [stack.env]
    environment:
      DATABASE_URL: postgres://revik_app:{{index .Credentials "runtime"}}@postgres:5432/revik?sslmode=disable
      REVIK_ENV: preview
      HTTP_PORT: "3111"
      WS_PORT: "3112"
      WS_SECRET: {{index .Credentials "bridge"}}
      ALLOWED_ORIGINS: https://{{.Host}}
      CLERK_AUTHORIZED_PARTIES: https://{{.Host}}
    networks: [db, app]
    depends_on:
      migrate: {condition: service_completed_successfully}
    healthcheck:
      test: [CMD, wget, -q, --spider, 'http://127.0.0.1:3111/health']
      interval: 5s
      timeout: 3s
      retries: 24
  godot-api:
    <<: *runtime
    mem_limit: {{index .Limits "godot-api"}}
    memswap_limit: {{index .Limits "godot-api"}}
    image: {{index .Images 2}}
    environment:
      PORT: "3110"
      GOLANG_WS_URL: ws://api:3112
      WS_SECRET: {{index .Credentials "bridge"}}
      REDIS_HOST: redis
      REDIS_PORT: "3113"
      TEST_MODE: "false"
      XDG_DATA_HOME: /tmp/godot
      XDG_CONFIG_HOME: /tmp/godot-config
    networks: [app]
    depends_on:
      api: {condition: service_healthy}
      redis: {condition: service_healthy}
  redis:
    <<: *runtime
    mem_limit: {{index .Limits "redis"}}
    memswap_limit: {{index .Limits "redis"}}
    image: redis:7-alpine@sha256:520775a41a63e77e06c73e35d2fd9cc15921a609516818796b4ecbb813078bc7
    user: "999:999"
    volumes: [redis_data:/data]
    command: [redis-server, --port, "3113", --save, "", --appendonly, "yes", --appendfsync, everysec, --maxmemory, 32mb, --maxmemory-policy, noeviction]
    networks: [app]
    healthcheck:
      test: [CMD, redis-cli, -p, "3113", ping]
      interval: 5s
      timeout: 3s
      retries: 12
  {{.Project}}-gate:
    <<: *runtime
    mem_limit: {{index .Limits "gate"}}
    memswap_limit: {{index .Limits "gate"}}
    image: {{index .Images 0}}
    container_name: {{.Project}}-gate
    environment:
      PREVIEW: "1"
      PR: "{{.PR}}"
      BASE_URL: https://{{.Host}}{{.BasePath}}
      PREVIEW_BASE_PATH: "{{.BasePath}}"
      PREVIEW_HOST: {{.Host}}
      PREVIEW_API_HOST: {{.APIHost}}
    ports: ["127.0.0.1:{{.GatePort}}:80"]
    networks: [app, shared]
    depends_on:
      api: {condition: service_healthy}
      godot-api: {condition: service_started}
networks:
  db: {internal: true}
  app: {}
  shared: {external: true, name: {{.Network}}}
volumes:
  pg_data: {}
  redis_data: {}
"
}

